INSERT INTO public.world_record_global (id_user,id_level,id_record,date_created,date_updated) VALUES($1,$2,$3,clock_timestamp(),clock_timestamp()) ON CONFLICT (id_level) DO UPDATE SET id_user=excluded.id_user,id_record=excluded.id_record,date_updated=excluded.date_updated WHERE (SELECT current_record.time FROM public.record current_record WHERE current_record.id=world_record_global.id_record)>$4 OR NOT zc_private.record_is_eligible(world_record_global.id_record) RETURNING id
